import { useState, type ReactNode } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";

export function CollapsibleCard({
  title = "Deploy", hint, icon = "\u25CE", iconTone, right, tone, defaultOpen = false, children = "Card content goes here.",
}: {
  title?: string; hint?: string; icon?: string; iconTone?: string; right?: ReactNode; tone?: string; defaultOpen?: boolean; children?: ReactNode;
}) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <Box radius="lg" bg="var(--bg-panel)" pad={[13, 14]} style={{
      border: "1px solid " + (tone ? `color-mix(in oklch, ${tone}, transparent 78%)` : "var(--border-soft)"),
    }}>
      <Row gap={8} align="center" style={{ cursor: "pointer" }} onClick={() => setOpen((o) => !o)}>
        {icon && <Text as="span" style={{ color: iconTone ?? tone ?? "var(--fg-muted)", fontSize: 14 }}>{icon}</Text>}
        <Box>
          <Text as="div" weight={600} size={13}>{title}</Text>
          {hint && <Text as="div" size={10.5} tone="muted" style={{ marginTop: 2 }}>{hint}</Text>}
        </Box>
        <Spacer />
        {right}
        <Text as="span" size={10} tone="dim" style={{ transform: open ? "rotate(90deg)" : "none", display: "inline-block" }}>{"\u25B8"}</Text>
      </Row>
      {open && <Box style={{ marginTop: 10 }}>{children}</Box>}
    </Box>
  );
}
